import React,{useState} from 'react';
import {createRoot} from 'react-dom/client';
import AdminShell from '../../admin/AdminShell';
import Finances from '../../admin/Finances';
import OrderCosts from '../../admin/OrderCosts';
import Stock from '../../admin/Stock';
import {stockSum,stockQuantity} from '../../shared/stock.mjs';
import {sessionRecovery} from '../../admin/session-recovery.mjs';
import '../../src/fonts.css';
import '../../admin/finance.css';
import '../../admin/stock.css';
const params=new URLSearchParams(location.search),scenario=params.get('scenario')||'normal',view=params.get('view')||'stock',now=Math.floor(Date.now()/1000),id=n=>`11111111-1111-4111-8111-${String(n).padStart(12,'0')}`;
const base=(n,name,unit,basis='per_order')=>({id:id(n),name,category:'materials',unit,basis,packCents:4500,packQuantity:20,usageMilli:1000,magnetsPerSheet:basis==='per_sheet'?9:null,active:true});
let entries=[base(1,'Magnet sheets','sheet','per_sheet'),base(2,'Protective coating','ml'),{...base(3,'Paper sleeves','sleeve'),category:'packaging'}, {...base(4,'Courier expense','delivery'),category:'courier'}],settingsVersion=2,revision=52,authenticated=true,failed=false,usage=null,usageVersion=0;
let items=entries.slice(0,2).map((entry,index)=>({id:entry.id,name:entry.name,unit:entry.unit,wholeUnits:index===0,balanceMilli:index===0?(scenario==='shortage'?1000:24000):180000,initialized:scenario!=='missing-setup',lowMilli:index===0?5000:50000,version:2,stocktakeGeneration:1}));
let history=Array.from({length:52},(_,index)=>({seq:52-index,operationId:id(100+index),kind:'receipt',created:now-index*3600,reason:'',price:{packCents:4500,packQuantity:20},lines:[{itemId:id(1),name:'Magnet sheets',unit:'sheet',deltaMilli:1000,balanceMilli:24000,stocktakeGeneration:1}]}));
const savedLines=entries.slice(0,2).map((entry,index)=>({...entry,unit:scenario==='mismatch'&&index===1?'bottle':entry.unit,usageMilli:index===0?2000:12500,excluded:false,amountCents:index===0?450:2813}));
const order={id:id(80),reference:'CV-LOCAL-STOCK',created:now-7200,expires:now+86400,status:'in_progress',version:3,snapshot:{magnetQty:11,subtotalCents:22000,deliveryCents:0,totalCents:22000,paymentStatus:'unpaid'}};
let cost=scenario==='no-saved-costs'?null:{orderId:order.id,version:2,orderVersion:3,status:'estimated',lines:savedLines,complete:true,totalCents:3263,knownCostCents:3263,updatedAt:now};
const operations=new Map(),clone=value=>structuredClone(value),respond=(value,status=200)=>Response.json(clone(value),{status}),failure=(code,message,status=409)=>respond({error:message,code},status);
const preview=()=>({orderId:order.id,orderVersion:order.version,costVersion:cost?.version??0,usageVersion,usage:usage&&{...usage,canReverse:!usage.lines.some(line=>items.find(item=>item.id===line.itemId)?.stocktakeGeneration!==line.stocktakeGeneration),reverseBlockedByStocktake:usage.lines.some(line=>items.find(item=>item.id===line.itemId)?.stocktakeGeneration!==line.stocktakeGeneration),lines:usage.lines.map(line=>({...line,version:items.find(item=>item.id===line.itemId)?.version??line.version}))},lines:(cost?.lines||[]).filter(line=>!line.excluded&&items.some(item=>item.id===line.id)).map(line=>{const item=items.find(item=>item.id===line.id),matches=line.unit.trim().toLowerCase()===item.unit.trim().toLowerCase();return {...item,itemId:item.id,suggestedMilli:matches?line.usageMilli:null,requiresQuantity:!matches};})});
if(scenario==='blocked-reversal'){usage={operationId:id(90),status:'active',lines:items.map((item,index)=>({itemId:item.id,version:item.version,stocktakeGeneration:1,quantityMilli:index?12500:2000}))};usageVersion=1;items[0].stocktakeGeneration=2;}
// Every runtime request is intercepted. No fallback to real fetch or email exists.
window.fetch=async(input,options={})=>{
 const url=new URL(typeof input==='string'?input:input.url,location.origin),post=options.method==='POST';
 if(url.origin!==location.origin)throw Error('External traffic is blocked in this local synthetic fixture.');
 if(url.pathname==='/api/session')return authenticated?respond({csrf:'synthetic-only',expiresAt:now+3600}):failure('UNAUTHORIZED','Synthetic sign-in expired.',401);
 if(!authenticated)return failure('UNAUTHORIZED','Synthetic sign-in expired.',401);
 const body=post?JSON.parse(options.body):null;
 if(post&&!url.pathname.startsWith('/api/stock/')&&!url.pathname.startsWith('/api/finance/'))return failure('FORBIDDEN','All email and other writes are blocked.',403);
 if(url.pathname==='/api/finance/settings')return respond({version:settingsVersion,entries,updatedAt:now});
 if(url.pathname==='/api/finance/month')return respond({month:url.searchParams.get('month'),reportRevision:1,validUntil:now+86400,rows:[],next:null,summary:{orderCount:0,magnetQty:0,knownOrderValueCents:0,recordedCostCents:0,projectedMarginCents:null,marginOrderCount:0,missingCostCount:0,estimatedCostCount:0,confirmedCostCount:0,missingTotalCount:0},availableFrom:now});
 if(url.pathname==='/api/finance/orders/'+order.id){if(post){cost={...cost,lines:body.lines,version:(cost?.version??0)+1,orderVersion:order.version,status:'estimated',complete:true,totalCents:3263,knownCostCents:3263};}return respond({orderId:order.id,orderVersion:order.version,cost});}
 if(url.pathname==='/api/finance/orders/'+order.id+'/confirm'&&post){cost={...cost,status:'confirmed',version:cost.version+1};return respond({orderId:order.id,orderVersion:order.version,cost});}
 if(!url.pathname.startsWith('/api/stock/'))return failure('FORBIDDEN','Non-fixture traffic is blocked.',403);
 if(!post){if(url.pathname==='/api/stock/items')return respond({revision,settingsVersion,items,costEntries:entries});if(url.pathname==='/api/stock/orders/'+order.id)return respond(preview());if(url.pathname==='/api/stock/history'){if(url.searchParams.has('revision')&&Number(url.searchParams.get('revision'))!==revision)return failure('CONFLICT','Stock changed.');const before=Number(url.searchParams.get('before')||Infinity),rows=history.filter(row=>row.seq<before).slice(0,50);return respond({revision,rows,next:history.some(row=>row.seq<(rows.at(-1)?.seq??0))?rows.at(-1).seq:null});}return failure('NOT_FOUND','Fixture route not found.',404);}
 if(scenario==='session-expired'&&!failed){failed=true;authenticated=false;return failure('UNAUTHORIZED','Synthetic sign-in expired.',401);}
 if(scenario==='conflict'&&!failed){failed=true;items[0].version++;return failure('CONFLICT','Changed in another synthetic tab.');}
 const previous=operations.get(body.operationId);if(previous)return JSON.stringify(body)===previous.request?respond(previous.result):failure('OPERATION_MISMATCH','Operation identity changed.');
 let kind,reason='',price=null,lines=[],next=clone(items),nextUsage=clone(usage),nextUsageVersion=usageVersion;
 const lookup=(itemId,version)=>{const item=next.find(item=>item.id===itemId);if(!item||item.version!==version)throw Error('CONFLICT');return item;};
 const move=(item,delta)=>{item.balanceMilli=stockSum(item.balanceMilli,delta);item.version++;lines.push({itemId:item.id,name:item.name,unit:item.unit,deltaMilli:delta,balanceMilli:item.balanceMilli,stocktakeGeneration:item.stocktakeGeneration});};
 try{
 if(url.pathname==='/api/stock/items'){kind='item';let item=next.find(item=>item.id===body.id);if(item){lookup(body.id,body.version);item.lowMilli=stockQuantity(body.lowMilli,item.wholeUnits);item.version++;}else{const entry=entries.find(entry=>entry.id===body.id);if(!entry||entry.category==='courier')return failure('INVALID','Choose a physical entry.',400);item={id:body.id,name:entry.name,unit:body.unit,wholeUnits:body.wholeUnits,balanceMilli:0,initialized:false,lowMilli:body.lowMilli,version:1,stocktakeGeneration:0};next.push(item);}lines=[{itemId:item.id,name:item.name,unit:item.unit,deltaMilli:0,balanceMilli:item.balanceMilli,stocktakeGeneration:item.stocktakeGeneration}];}
 else if(url.pathname==='/api/stock/receipts'){kind='receipt';const item=lookup(body.itemId,body.version);move(item,stockQuantity(body.quantityMilli,item.wholeUnits));price=body.packCents===null?null:{packCents:body.packCents,packQuantity:body.packQuantity};if(body.updateDefault){if(body.settingsVersion!==settingsVersion)return failure('CONFLICT','Cost defaults changed.');entries=entries.map(entry=>entry.id===body.itemId?{...entry,packCents:body.packCents,packQuantity:body.packQuantity}:entry);settingsVersion++;}}
 else if(url.pathname==='/api/stock/stocktake'){kind='stocktake';reason=body.reason;const item=lookup(body.itemId,body.version);stockQuantity(body.countedMilli,item.wholeUnits);item.stocktakeGeneration++;item.initialized=true;move(item,body.countedMilli-item.balanceMilli);}
 else if(url.pathname==='/api/stock/orders/'+order.id+'/use'){kind='use';if(usage?.status==='active')return failure('ALREADY_USED','Materials already used.');if(body.orderVersion!==order.version||body.costVersion!==cost?.version||body.usageVersion!==usageVersion)return failure('CONFLICT','Order changed.');for(const line of body.lines){const item=lookup(line.itemId,line.version);if(!item.initialized)return failure('INVALID','Record a starting stocktake.',400);if(line.quantityMilli>item.balanceMilli)return failure('SHORTAGE','Not enough stock.');move(item,-line.quantityMilli);}nextUsage={operationId:body.operationId,status:'active',lines:body.lines,canReverse:true,reverseBlockedByStocktake:false};nextUsageVersion++;}
 else if(url.pathname==='/api/stock/orders/'+order.id+'/reverse'){kind='reverse';reason=body.reason;if(!usage||usage.status!=='active')return failure('CONFLICT','No active use.');if(!preview().usage.canReverse)return failure('STOCKTAKE_AFTER_USE','A later stocktake prevents reversal.');for(const line of body.lines){const item=lookup(line.itemId,line.version),used=usage.lines.find(used=>used.itemId===line.itemId);move(item,used.quantityMilli);}nextUsage={...usage,status:'reversed',canReverse:false};nextUsageVersion++;}
 else return failure('FORBIDDEN','Unknown writes are blocked.',403);
 }catch(error){return failure(error.message==='CONFLICT'?'CONFLICT':'INVALID','Synthetic request rejected.',error.message==='CONFLICT'?409:400);}
 items=next;usage=nextUsage;usageVersion=nextUsageVersion;history.unshift({seq:++revision,operationId:body.operationId,kind,created:now,reason,price,lines});const result={operationId:body.operationId,revision,items,usage:preview().usage};operations.set(body.operationId,{request:JSON.stringify(body),result:clone(result)});if(scenario==='lost-response'&&!failed){failed=true;throw new TypeError('Synthetic response lost after saving.');}return respond(result);
};
navigator.sendBeacon=()=>false;
const fixture='/tests/fixtures/admin-stock.html';document.addEventListener('click',event=>{const link=event.target.closest('a');if(!link)return;const url=new URL(link.href);if(url.origin!==location.origin){event.preventDefault();return;}if(url.pathname===fixture)return;event.preventDefault();if(url.pathname==='/auth/login'){authenticated=true;sessionRecovery.check();}else if(url.pathname==='/finances')location.href=fixture+'?view=finances&scenario='+scenario;else if(url.pathname==='/orders')location.href=fixture+'?view=order&scenario='+scenario;});
function Fixture(){const [tick,setTick]=useState(0);return <><div className="cv-stock-fixture-bar" style={{padding:'12px 20px',background:'#35233f',color:'#fff',font:'13px system-ui',display:'flex',gap:12,flexWrap:'wrap',alignItems:'center'}}><span>LOCAL SYNTHETIC PREVIEW · No external traffic, email or production writes · {scenario}</span><a style={{color:'#fff'}} href={fixture+'?view=stock&scenario='+scenario}>Stock</a><a style={{color:'#fff'}} href={fixture+'?view=order&scenario='+scenario}>Order costs</a><a style={{color:'#fff'}} href={fixture+'?view=finances&scenario='+scenario}>Finances tabs</a>{scenario==='session-expired'&&<button className="cv-btn secondary" onClick={()=>{authenticated=true;sessionRecovery.check();}}>Restore synthetic sign-in</button>}</div><AdminShell section="finances" logout={()=>{authenticated=false;sessionRecovery.expired();}}>{view==='order'?<main className="cv-finances"><h1>{order.reference}</h1><p>11 magnets · Unpaid · Synthetic production order</p><button className="cv-btn secondary" onClick={()=>{order.version++;setTick(tick+1);}}>Advance synthetic stage</button><p>Stage version {order.version}. This action never moves stock or sends email.</p><OrderCosts order={{...order}}/></main>:view==='finances'?<Finances/>:<main className="cv-finances"><h1>Finances</h1><Stock/></main>}</AdminShell></>;}
createRoot(document.getElementById('root')).render(<Fixture/>);
